def calc(n0):
    MOD = 1000000007
    def modexp(a, b, mod):
        res = 1
        while b > 0:
            if b % 2:
                res = (res * a) % mod
            a = (a * a) % mod
            b //= 2
        return res
    ans = modexp(2, int(n0), MOD) - 1
    return ans if ans >= 0 else ans + MOD

def calc(n0):
    MOD = 1000000007
    def expo(a, b, mod):
        res = 1
        a = a % mod
        while b > 0:
            if b % 2:
                res = (res * a) % mod
            a = (a * a) % mod
            b //= 2
        return res
    return (expo(2, int(n0), MOD) - 1) % MOD

