def calc(a, b):
    n = len(a)
    if n == 0 or not b:
        return [0]*len(b)
    prefix = [0]*n
    prefix[0] = a[0]
    for i in range(1, n):
        prefix[i] = prefix[i-1] + a[i]
    res = []
    for l, r in b:
